examples.reactComponent:
import { useEffect, useState } from 'react';
import io from 'socket.io-client';

function ChatComponent({ token, recipientId }) {
  const [socket, setSocket] = useState(null);
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [recipientOnline, setRecipientOnline] = useState(false);

  useEffect(() => {
    const newSocket = io('http://localhost:3000/chat', {
      auth: { token }
    });

    // Listen for new messages
    newSocket.on('newMessage', (message) => {
      setMessages(prev => [...prev, message]);
      // Mark as delivered
      newSocket.emit('markAsDelivered', { messageIds: [message.id] });
    });

    // Listen for message sent confirmation
    newSocket.on('messageSent', (data) => {
      setMessages(prev => [...prev, data]);
      setRecipientOnline(data.recipientOnline);
    });

    // Listen for typing indicator
    newSocket.on('userTyping', (data) => {
      if (data.userId === recipientId) {
        console.log('User is typing:', data.isTyping);
      }
    });

    setSocket(newSocket);

    return () => newSocket.close();
  }, [token, recipientId]);

  const sendMessage = () => {
    if (socket && input.trim()) {
      socket.emit('sendMessage', {
        recipientId,
        content: input
      });
      setInput('');
    }
  };

  return (
    <div>
      <div>Status: {recipientOnline ? '🟢 Online' : '⚫ Offline'}</div>
      <div>
        {messages.map(msg => (
          <div key={msg.id}>
            <p>{msg.content}</p>
            <small>
              {msg.isDelivered ? '✓✓' : '✓'}
              {msg.isRead ? ' Read' : ''}
            </small>
          </div>
        ))}
      </div>
      <input
        value={input}
        onChange={(e) => setInput(e.target.value)}
        onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
      />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}
